<template>
  <AlertMessages></AlertMessages>
  <LoadingView :active="isLoading">
    <div class="loadingio-spinner-pulse-glqepjl9sp">
      <div class="ldio-wiw3itsk6ko">
        <div></div>
        <div></div>
        <div></div>
      </div>
    </div>
  </LoadingView>
  <router-view/>
</template>

<script>
import AlertMessages from '@/components/AlertModal.vue'
export default {
  data () {
    return {
      isLoading: false
    }
  },
  components: {
    AlertMessages
  },
  methods: {
    generateCartId () {
      // 生成 16 位元隨機字串
      const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'
      let result = ''
      for (let i = 0; i < 16; i++) {
        result += characters.charAt(Math.floor(Math.random() * characters.length))
      }
      return result
    },
    initializeCartId () {
      if (!localStorage.getItem('cart_id')) {
        const cartId = this.generateCartId()
        localStorage.setItem('cart_id', cartId)
        console.log(`Generated cart_id: ${cartId}`)
      } else {
        console.log(`Existing cart_id: ${localStorage.getItem('cart_id')}`)
      }
    }
  },
  mounted () {
    this.$emitter.on('isLoading', (status) => {
      console.log(status)
      this.isLoading = status
    })
    this.initializeCartId() // 初始化 cart_id
  }
}
</script>

